import{c as t,Q as l,j as a,m as i}from"./chunks/framework.DOi4mjdC.js";const s="/assets/%E7%AE%97%E5%AD%90%E7%A8%8B%E5%BA%8F%E4%B8%AD%E4%B8%89%E7%A7%8D%E5%87%BD%E6%95%B0%E9%97%B4%E7%9A%84%E8%B0%83%E7%94%A8%E5%85%B3%E7%B3%BB.KHLoXYpl.png",h=JSON.parse('{"title":"核函数","description":"","frontmatter":{},"headers":[{"level":1,"title":"核函数","slug":"核函数"},{"level":2,"title":"核函数的定义","slug":"核函数的定义"},{"level":2,"title":"核函数的调用","slug":"核函数的调用"}],"relativePath":"guide/编程指南/编程模型/AI-Core-SIMT编程/核函数.md","filePath":"guide/编程指南/编程模型/AI-Core-SIMT编程/核函数.md"}'),o={name:"guide/编程指南/编程模型/AI-Core-SIMT编程/核函数.md"};function n(r,e,d,p,c,_){return l(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="核函数" tabindex="-1">核函数 <a class="header-anchor" href="#核函数" aria-label="Permalink to &quot;核函数&quot;">​</a></h1><h2 id="核函数的定义" tabindex="-1">核函数的定义 <a class="header-anchor" href="#核函数的定义" aria-label="Permalink to &quot;核函数的定义&quot;">​</a></h2><p>Ascend C支持开发者自定义核函数来扩展C++，核函数在AI处理器上执行时实际是若干线程在并行执行，每个线程有独立的寄存器和栈，共同完成数据计算任务。</p><p>核函数的定义示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> __global__ void kernel_name(argument list)</span></span></code></pre></div><p>定义核函数时需要遵循以下规则：</p><ul><li>使用函数类型限定符__global__， 标识它是一个核函数。</li><li>核函数必须具有void返回类型。</li><li>函数入参支持的类型如下： <ul><li>基础数据类型，如int32_t、float等。</li><li>基础数据类型的指针类型，如int32_t*、float*等，实际上这些指针指向的是GlobalMemory内存。</li></ul></li></ul><h2 id="核函数的调用" tabindex="-1">核函数的调用 <a class="header-anchor" href="#核函数的调用" aria-label="Permalink to &quot;核函数的调用&quot;">​</a></h2><p>算子程序中的函数可以分为三类：host侧执行函数、核函数（device侧执行）、device侧执行函数（除核函数之外）。下图以Kernel直调算子开发方式为例，描述三者的调用关系：</p><ul><li>host侧执行函数可以调用其它host执行函数，也就是通用C/C++编程中的函数调用；也可以通过&lt;&lt;&lt;...&gt;&gt;&gt;调用核函数。</li><li>核函数可以调用除核函数之外的其它device侧执行函数。</li><li>device侧执行函数（除核函数之外）使用类型限定符__aicore__标识，可以调用同类的其它device侧执行函数。</li></ul><p><strong>图 1</strong> 算子程序中三种函数间的调用关系<br><img src="'+s+'" alt="" title="算子程序中三种函数间的调用关系"></p><p>Host侧通过内核调用符&lt;&lt;&lt;...&gt;&gt;&gt;的语法形式调用核函数，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kernel_name&lt;&lt;&lt;numBlocks, threadsPerBlock, dynUBufSize, stream&gt;&gt;&gt;(args...)</span></span></code></pre></div><p>执行配置由4个参数决定：</p><ul><li>numBlocks：为核函数配置的线程块的个数，即启用的核数, 支持int32_t和dim3类型；</li><li>threadsPerBlock：每个线程块内并发执行的线程数量，支持int32_t和dim3类型；</li><li>dynUBufSize：动态申请内存空间总大小，一般情况设置为0；</li><li>stream：用于host侧和device侧的流同步。</li></ul>',15)])])}const g=t(o,[["render",n]]);export{h as __pageData,g as default};
